create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.BESCH_LIEF_2 (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Der Mandant_2 1 steht im DWH für Deutschland (der Wert 222 aus dem SAP System für Deutschland wird in Wert 1 umgewandelt).',
	LIEF_BELEG_ID NUMBER(38,0) NOT NULL COMMENT 'Das Feld enthält die Beleg ID des Lieferscheins und dient der eindeutigen Identifikation der Lieferscheinbelege.',
	KJ NUMBER(38,0) NOT NULL COMMENT 'Kalenderjahr, Format JJJJ.',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Mutter Wup_2 ID, wird verwendet für Beziehung Lager zu Verteilzentrum.',
	NB_ID NUMBER(38,0) COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer',
	VERSANDSTELLE_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Ort, an dem Lieferungen bearbeitet werden. Es kann sich dabei um einen physischen Ort (z.B. ein Lager oder eine_2 Gruppe_2 von Laderampen) oder um eine_2 logische Gruppierung (z.B. eine_2 Gruppe_2 von Personen, die für die Versandaktivitäten zuständig ist) handeln.',
	VERKAUFSORGANISATION_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Organisatorische Einheit, die für den Vertrieb bestimmter Produkte oder Dienstleistungen verantwortlich ist, z. B. KL = Kaufland.',
	LIEF_TYP_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Klassifikation, mit der zwischen verschiedenen Arten der Lieferung unterschieden wird. Die Lieferart bestimmt, wie das System eine_2 Lieferung bearbeitet.',
	DAT_LIEF_SOLL DATE NOT NULL COMMENT 'Datum, bei dem die Lieferung beim Kunden eingehen soll. Das System kann für den Warenausgang das Lieferdatum aufgrund vordefinierter Zeitschätzungen errechnen.',
	VERTR_BELEG_TYP_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Dieses Kennzeichen liefert die Information aus welchem Vorgang dieser Vertriebsbeleg generiert wurde, z. B. ob der Lieferschein aufgrund eines Wareneingangs generiert wurde.',
	LIEF_PAL_TYP_ID VARCHAR(1) NOT NULL COMMENT 'Der Palettentyp einer Lieferung kennzeichnet, ob es sich um eine_2 Ganzpalettenlieferung, Mischpalettenlieferung, Lieferung je Markt etc. handelt.',
	KUNDE_ID VARCHAR(10) NOT NULL COLLATE 'en-ci' COMMENT 'Nummer des Warenempfängers der Lieferung. Diese Nummer referenziert die DWH Tabelle wup. COMPRESS mit CAMSET_L.',
	AUFTRAGGEBER_ID VARCHAR(10) NOT NULL COLLATE 'en-ci' COMMENT 'Kunde, der die Waren oder Dienstleistungen bestellt. Der Auftraggeber übernimmt die vertragliche Haftung für den Kundenauftrag. COMPRESS mit CAMSET_L.',
	ANZAHL_PACKSTUECK NUMBER(38,0) COMMENT 'Gesamte Anzahl der Packstücke für alle Positionen der Lieferung.',
	WERBEWARE_ID VARCHAR(1) COLLATE 'en-ci' COMMENT 'Wird gefüllt, wenn die Bestellart eine_2 Werbebestellart ist. Wertevorrat: W = Werbung, N = Normalware, B-W und N-S = Schnellschuss.',
	DAT_LAGERBEW_IST DATE COMMENT 'Warenbewegungsdatum im Lieferschein.',
	SYSTEM_ID NUMBER(38,0) NOT NULL DEFAULT 7 COMMENT 'Die System ID kennzeichnet das Quellsystem der Daten (z. B. SAP PR1).',
	MANDANT_ID_KUNDE NUMBER(38,0) NOT NULL DEFAULT 1 COMMENT 'Der Kunde kann zu einem anderen Mandanten als dem des WUP_2 gehören, z.B. Lager aus CZ beliefert Markt in SK.',
	CD_KZ VARCHAR(2) NOT NULL COLLATE 'en-ci' COMMENT 'Kennzeichen für Cross Docking aus zlvcd.  Referenz zur Lookuptabelle l_cd_typ.',
	WUP_ID_CD NUMBER(38,0) NOT NULL COMMENT 'Nummer des Verteilzentrums bei CD-Verkehren.',
	LAGERNUMMER_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'ID der Lagernummer - höchste Ebene der Lagerhierarchie.',
	STELLPLATZ_FAKTOR NUMBER(38,2) NOT NULL DEFAULT 1 COMMENT 'Korrekturwert zur Berechnung der Anzahl der Stellplätze.',
	BELOS_VORGANG_ID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Referenz zum Belos-Vorgang. Nicht in jedem Fall vorhanden. Defaultwert ist 0.',
	HANDLING_UNIT_ID_EXT VARCHAR(20) NOT NULL COLLATE 'en-ci' DEFAULT '-1' COMMENT 'Die 18-stellige Nummer der Versandeinheit (NVE) aus dem Feld zzlvcdnve. Aus Konsistenzgründen als varchar(20) mit zwei führenden Nullen abgespeichert. COMPRESS mit CAMSET_L.',
	WG_VERKETT_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag. Zeigt an, ob eine_2 Warengruppenverkettung existiert. Aus dem Feld zzlvwgrvkhier_kz.',
	WG_VERKETT_LIEF NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Die Warengruppenverkettung ist artikelbezogen. Wird in SAP auf die Kopftabelle hochgezogen, die erste Position als Quelle. Stimmt also bei Mischpaletten nicht für alle Positionen. Referenziert auf die Tabelle l_wg_verkettung. Das SAP-Feld ist zzlwgrv.',
	GP_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Geschäftspartner - ID (Lieferanten - ID). Entspricht elifn aus der Quelle.',
	WE_STATUS_ID VARCHAR(1) NOT NULL COLLATE 'en-ci' DEFAULT '-' COMMENT 'Wareneingangsstatus-ID, aus zlvwestatus.',
	DAT_AKTION DATE COMMENT 'Werbedatum.',
	DAT_ERSTELLUNG DATE COMMENT 'Erstellungsdatum des Lieferbeleges - Quelle: LIKP.ERDAT.',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	constraint PK_BESCH_LIEF primary key (MANDANT_ID, LIEF_BELEG_ID, KJ)
)COMMENT='TP408_LVS - In dieser Tabelle sind die Kopfdaten der Lieferscheine aus der SAP Tabelle LIPK enthalten.'
;
